SET NAMES utf8mb4;
START TRANSACTION;

DROP TABLE IF EXISTS bom_item_color_detail;
DROP TABLE IF EXISTS bom_item;
DROP TABLE IF EXISTS bom_parts;
DROP TABLE IF EXISTS bom_colorway;
DROP TABLE IF EXISTS bom_header;

CREATE TABLE bom_header (
    id INT AUTO_INCREMENT PRIMARY KEY,
    sample_order_no VARCHAR(100),
    sample_type VARCHAR(100),
    create_date VARCHAR(50),
    print_date VARCHAR(50),
    season VARCHAR(50),
    request_finish_date VARCHAR(50),
    gender VARCHAR(50),
    style_no VARCHAR(100),
    style_name VARCHAR(200),
    last_no VARCHAR(100),
    bottom_no VARCHAR(100),
    shoe_filler_no VARCHAR(100),
    shoetype VARCHAR(200),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE bom_colorway (
    id INT AUTO_INCREMENT PRIMARY KEY,
    header_id INT,
    color_code VARCHAR(100),
    FOREIGN KEY (header_id) REFERENCES bom_header(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE bom_parts (
    id INT AUTO_INCREMENT PRIMARY KEY,
    header_id INT,
    part_seq INT,
    part_name VARCHAR(200),
    FOREIGN KEY (header_id) REFERENCES bom_header(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE bom_item (
    id INT AUTO_INCREMENT PRIMARY KEY,
    header_id INT,
    part_id INT,
    item_seq INT,
    material_desc TEXT,
    unit VARCHAR(50),
    remark VARCHAR(255),
    supplier VARCHAR(200),
    FOREIGN KEY (header_id) REFERENCES bom_header(id) ON DELETE CASCADE,
    FOREIGN KEY (part_id) REFERENCES bom_parts(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE bom_item_color_detail (
    id INT AUTO_INCREMENT PRIMARY KEY,
    bom_item_id INT,
    colorway_id INT,
    material_color_spec TEXT,
    process_desc TEXT,
    FOREIGN KEY (bom_item_id) REFERENCES bom_item(id) ON DELETE CASCADE,
    FOREIGN KEY (colorway_id) REFERENCES bom_colorway(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;










